'use strict';
// Nightly. For each agent: how many ratings their tickets received in the past seven days, and the average score.
// The agent is the owner at the time of the rating. One summary per agent, replaced on every run.

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyCsat(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const r of store.listRatings()) {
    if (r.agent_id == null) continue;
    if (new Date(r.rated_at).getTime() < since) continue;
    const scores = byAgent.get(r.agent_id) || [];
    scores.push(r.score);
    byAgent.set(r.agent_id, scores);
  }
  const summaries = [];
  for (const [agentId, scores] of byAgent) {
    const average = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100;
    const summary = { agent_id: agentId, computed_at: now.toISOString(), ratings: scores.length, average };
    store.saveAgentSummary(agentId, summary);
    summaries.push(summary);
  }
  return summaries;
}

module.exports = { weeklyCsat, WINDOW_DAYS };
```

